"use server";

import { redirect } from "next/navigation";
import { revalidatePath } from "next/cache";
import { cookies, headers } from "next/headers";
import bcrypt from "bcryptjs";
import { z } from "zod";
import { db } from "./db";
import { createSession, destroySession, requireUser, requireAdmin, currentUser } from "./auth";
import { capacityCheck } from "./capacity";
import { vpsTerm, vpsTermPriceCents, addMonths } from "./billing-terms";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { DEDICATED_IP_PRICE_CENTS } from "./dedicated-ip";
import { generateReferralCode } from "./growth";
import { grantSignupCredit, maybeRewardReferral, applyCouponToTopup } from "./actions-growth";
import { loginRateLimit, resetRateLimit } from "./rate-limit";
import { verifyTotpForUser } from "./actions-2fa";

/** Cookie the register page sets when a visitor arrives via a referral link. */
const REF_COOKIE = "nxeon_ref";
/** Cookie the billing CouponField sets when a promo code is applied. */
const COUPON_COOKIE = "nxeon_coupon";

/** Allocate a referral code that is unique in the DB (retry on the rare clash). */
async function uniqueReferralCode(): Promise<string> {
  for (let i = 0; i < 6; i++) {
    const code = generateReferralCode();
    const clash = await db.user.findUnique({ where: { referralCode: code } });
    if (!clash) return code;
  }
  // Extremely unlikely; fall back to a longer code.
  return generateReferralCode(12);
}

async function audit(userId: string | null, action: string, detail?: string) {
  await db.auditLog.create({ data: { userId, action, detail } });
}

// ---------- Auth ----------

const credsSchema = z.object({
  email: z.string().email().max(200),
  password: z.string().min(8).max(200),
});

export async function register(prev: any, formData: FormData): Promise<{ error?: string }> {
  const parsed = credsSchema.extend({ name: z.string().min(1).max(100) }).safeParse({
    email: formData.get("email"),
    password: formData.get("password"),
    name: formData.get("name"),
  });
  if (!parsed.success) return { error: "Enter a valid email, name, and password (min 8 chars)." };
  const { email, password, name } = parsed.data;

  const existing = await db.user.findUnique({ where: { email } });
  if (existing) return { error: "An account with that email already exists." };

  // Capture a referral from the `ref` cookie (set by the register page) if the
  // code maps to a real user. Self-referral is impossible here (new account).
  const jar = await cookies();
  const refCode = jar.get(REF_COOKIE)?.value?.trim().toUpperCase();
  let referredById: string | null = null;
  if (refCode) {
    const referrer = await db.user.findUnique({ where: { referralCode: refCode } });
    if (referrer) referredById = referrer.id;
  }

  const referralCode = await uniqueReferralCode();
  const user = await db.user.create({
    data: {
      email,
      name,
      passwordHash: await bcrypt.hash(password, 12),
      referralCode,
      referredById,
    },
  });
  await audit(user.id, "user.register", referredById ? `ref=${refCode}` : undefined);
  // Grant signup free credit (no-op unless SIGNUP_FREE_CREDIT_CENTS > 0).
  try {
    await grantSignupCredit(user.id);
  } catch { /* non-fatal */ }
  jar.delete(REF_COOKIE);
  try {
    const { sendMail, emails } = await import("./mailer");
    const tpl = emails.welcome(name);
    await sendMail({ to: email, subject: tpl.subject, html: tpl.html });
  } catch { /* email is best-effort */ }
  await createSession(user.id);
  redirect("/dashboard");
}

export async function login(
  prev: any,
  formData: FormData,
): Promise<{ error?: string; needs2fa?: boolean }> {
  const parsed = credsSchema.safeParse({
    email: formData.get("email"),
    password: formData.get("password"),
  });
  if (!parsed.success) return { error: "Invalid email or password." };

  // App-level throttle: 5 attempts / 15 min per email+IP.
  const hdrs = await headers();
  const ip = (hdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
  const rlId = `${parsed.data.email}:${ip}`;
  const rl = loginRateLimit(rlId);
  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };

  const user = await db.user.findUnique({ where: { email: parsed.data.email } });
  if (!user || !(await bcrypt.compare(parsed.data.password, user.passwordHash))) {
    return { error: "Invalid email or password." };
  }
  if (user.suspended) return { error: "This account is suspended." };

  // Two-factor challenge, if enabled on the account.
  if (user.totpEnabled) {
    const code = String(formData.get("code") ?? "").trim();
    if (!code) return { error: "Enter your 2FA code to continue.", needs2fa: true };
    if (!(await verifyTotpForUser(user.id, code))) {
      return { error: "Invalid 2FA code.", needs2fa: true };
    }
  }

  resetRateLimit(`login:${rlId}`);
  await audit(user.id, "user.login");
  await createSession(user.id);
  redirect(user.role === "ADMIN" ? "/admin" : "/dashboard");
}

export async function logout() {
  await destroySession();
  redirect("/login");
}

// ---------- Ordering ----------

const orderSchema = z.object({
  planId: z.string().min(1),
  osTemplateId: z.string().min(1),
  hostname: z
    .string()
    .min(3)
    .max(40)
    .regex(/^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i, "Hostname: letters, digits, hyphens"),
});

/** Pick the least-committed enabled node (RAM headroom). Falls back to primary. */
async function scheduleNode(planRamMB: number) {
  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
  if (nodes.length === 0) return null;
  const loads = await Promise.all(
    nodes.map(async (n) => {
      const agg = await db.server.findMany({
        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
        select: { plan: { select: { ramMB: true } } },
      });
      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
      return { node: n, free: n.capacityRamMB - used };
    })
  );
  loads.sort((a, b) => b.free - a.free);
  const best = loads[0];
  if (best.free < planRamMB) return best.node; // oversell guard handled by capacityCheck; still return best
  return best.node;
}

export async function orderServer(prev: any, formData: FormData): Promise<{ error?: string }> {
  const user = await requireUser();
  const parsed = orderSchema.safeParse({
