"use server";

import { redirect } from "next/navigation";
import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "./db";
import { requireUser } from "./auth";
import { requireArea } from "./rbac";
import { debitWallet, InsufficientBalanceError } from "./wallet";
import { addMonths } from "./billing-terms";
import { GAME_FAMILIES, type GameFamily } from "./games";

/**
 * Game servers as a distinct product. A `GamePlan` is one pricing tier for one
 * game (Minecraft 2 GB / 10 slots, etc). Admins (billing area) manage the
 * catalogue; customers order a tier, which provisions a VM sized by the tier's
 * base VPS Plan running the game's OsTemplate image.
 *
 * This module owns:
 *   - adminSaveGamePlan / adminToggleGamePlan / adminDeleteGamePlan (CRUD)
 *   - orderGameServer (customer deploy) — mirrors lib/actions.ts orderServer.
 */

type Result = { error?: string; ok?: boolean };

// ---------- Admin CRUD ----------

const planSchema = z.object({
  id: z.string().optional(),
  gameFamily: z.enum(GAME_FAMILIES),
  name: z.string().min(2).max(80),
  ramMB: z.coerce.number().int().min(256).max(262144),
  cpuCores: z.coerce.number().int().min(1).max(64),
  diskGB: z.coerce.number().int().min(1).max(4096),
  slots: z.coerce.number().int().min(1).max(100000).optional(),
  priceCents: z.coerce.number().int().min(0).max(100000000),
  termMonths: z.coerce.number().int().min(1).max(36),
  basePlanId: z.string().min(1),
  osTemplateId: z.string().optional(),
  sortOrder: z.coerce.number().int().min(0).max(100000),
});

/**
 * Create or update a GamePlan tier. ADMIN/BILLING only, audit-logged. Validates
 * the chosen base VPS Plan (sizing source) and the game OsTemplate (must belong
 * to the same game family, if provided).
 */
export async function adminSaveGamePlan(prev: Result | undefined, formData: FormData): Promise<Result> {
  const admin = await requireArea("billing");

  const rawSlots = String(formData.get("slots") ?? "").trim();
  const rawOs = String(formData.get("osTemplateId") ?? "").trim();
  const parsed = planSchema.safeParse({
    id: formData.get("id") || undefined,
    gameFamily: formData.get("gameFamily"),
    name: formData.get("name"),
    ramMB: formData.get("ramMB"),
    cpuCores: formData.get("cpuCores"),
    diskGB: formData.get("diskGB"),
    slots: rawSlots === "" ? undefined : rawSlots,
    priceCents: formData.get("priceCents"),
    termMonths: formData.get("termMonths"),
    basePlanId: formData.get("basePlanId"),
    osTemplateId: rawOs === "" ? undefined : rawOs,
    sortOrder: formData.get("sortOrder") ?? 0,
  });
  if (!parsed.success) {
    return { error: parsed.error.issues[0]?.message ?? "Check the tier values." };
  }
  const d = parsed.data;

  const base = await db.plan.findUnique({ where: { id: d.basePlanId } });
  if (!base) return { error: "Choose a valid base VPS plan for provisioning." };

  let osTemplateId: string | null = null;
  if (d.osTemplateId) {
    const os = await db.osTemplate.findUnique({ where: { id: d.osTemplateId } });
    if (!os) return { error: "Selected game image not found." };
    if (os.family !== d.gameFamily) {
      return { error: `That image belongs to "${os.family}", not "${d.gameFamily}".` };
    }
    osTemplateId = os.id;
  }

  const featured = formData.get("featured") === "on";
  const active = formData.get("active") === "on";

  const data = {
    gameFamily: d.gameFamily,
    name: d.name.trim(),
    ramMB: d.ramMB,
    cpuCores: d.cpuCores,
    diskGB: d.diskGB,
    slots: d.slots ?? null,
    priceCents: d.priceCents,
    termMonths: d.termMonths,
    basePlanId: d.basePlanId,
    osTemplateId,
    featured,
    active,
    sortOrder: d.sortOrder,
  };

  if (d.id) {
    const existing = await db.gamePlan.findUnique({ where: { id: d.id } });
    if (!existing) return { error: "Tier not found." };
    await db.gamePlan.update({ where: { id: d.id }, data });
  } else {
    await db.gamePlan.create({ data });
  }

  await db.auditLog.create({
    data: {
      userId: admin.id,
      action: d.id ? "gameplan.update" : "gameplan.create",
      detail: `${data.gameFamily} — ${data.name} (${(data.priceCents / 100).toFixed(2)}/${data.termMonths}mo)`,
    },
  });
  revalidatePath("/admin/game-plans");
  return { ok: true };
}

/** Flip a tier's active flag. */
export async function adminToggleGamePlan(id: string): Promise<void> {
  const admin = await requireArea("billing");
  const gp = await db.gamePlan.findUnique({ where: { id } });
  if (!gp) return;
  await db.gamePlan.update({ where: { id }, data: { active: !gp.active } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "gameplan.toggle", detail: `${gp.name} → active=${!gp.active}` },
  });
  revalidatePath("/admin/game-plans");
}

/** Delete a tier. Refused while servers reference it. */
export async function adminDeleteGamePlan(id: string): Promise<Result> {
  const admin = await requireArea("billing");
  const gp = await db.gamePlan.findUnique({
    where: { id },
    include: { _count: { select: { servers: true } } },
  });
  if (!gp) return { error: "Tier not found." };
  if (gp._count.servers > 0) {
    return { error: `Can't delete — ${gp._count.servers} server(s) use this tier. Disable it instead.` };
  }
  await db.gamePlan.delete({ where: { id } });
  await db.auditLog.create({
    data: { userId: admin.id, action: "gameplan.delete", detail: `${gp.gameFamily} — ${gp.name}` },
  });
  revalidatePath("/admin/game-plans");
  return { ok: true };
}

// ---------- Customer deploy ----------

/** Short random suffix so auto-generated hostnames don't collide. */
function rand(n = 6): string {
  return Math.random().toString(36).slice(2, 2 + n);
}

/**
 * Order a game server from a GamePlan tier. Mirrors lib/actions.ts orderServer:
 * validate the tier, atomically debit the wallet for `gamePlan.priceCents`, then
 * create the Server (sized by the tier's base VPS plan, running the game image)
 * plus a PROVISION Job in one transaction. Redirects to the new server.
 */
export async function orderGameServer(gamePlanId: string): Promise<Result> {
  const user = await requireUser();

  const gp = await db.gamePlan.findUnique({
    where: { id: gamePlanId },
    include: { basePlan: true },
  });
  if (!gp || !gp.active) return { error: "That game plan isn't available." };
  if (!gp.basePlan?.active) return { error: "Provisioning is temporarily unavailable for this game." };
  if (!GAME_FAMILIES.includes(gp.gameFamily as GameFamily)) {
    return { error: "Unknown game family." };
  }

  // Resolve the game image: the tier's own OsTemplate, else any active image for
  // this game family. A game server can't provision without an image.
  let osTemplateId = gp.osTemplateId;
  if (osTemplateId) {
    const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
    if (!os?.active) osTemplateId = null;
  }
  if (!osTemplateId) {
    const os = await db.osTemplate.findFirst({
      where: { family: gp.gameFamily, category: "APPLICATION", active: true },
      orderBy: { sortOrder: "asc" },
    });
    if (!os) return { error: "No game image is configured for this game yet." };
    osTemplateId = os.id;
  }

  const chargeCents = gp.priceCents;
  if (user.balanceCents < chargeCents) {
    return { error: "Insufficient balance. Top up your wallet first." };
  }

  const hostname = `${gp.gameFamily}-${rand()}`;

  let server;
  try {
    server = await db.$transaction(async (tx) => {
      await debitWallet(tx, user.id, chargeCents);
      await tx.walletTransaction.create({
        data: {
          userId: user.id,
          amountCents: -chargeCents,
          description: `Game server: ${gp.name} (${gp.gameFamily})`,
        },
      });
      const s = await tx.server.create({
        data: {
          name: hostname,
          hostname,
          userId: user.id,
          planId: gp.basePlanId,
          gamePlanId: gp.id,
          osTemplateId: osTemplateId!,
          termMonths: gp.termMonths,
          wantsDedicatedIp: false,
          expiresAt: addMonths(new Date(), gp.termMonths),
        },
      });
      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
      return s;
    });
  } catch (e) {
    if (e instanceof InsufficientBalanceError) {
      return { error: "Insufficient balance. Top up your wallet first." };
    }
    throw e;
  }

  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "gameserver.order",
      detail: `${server.id} game=${gp.gameFamily} tier=${gp.name}`,
    },
  });
  redirect(`/dashboard/servers/${server.id}`);
}

"use client";

import { useActionState, useEffect, useRef, useState, useTransition } from "react";
import {
  adminSaveGamePlan,
  adminToggleGamePlan,
  adminDeleteGamePlan,
} from "@/lib/actions-gameplans";

export type PlanOpt = { id: string; name: string; ramMB: number; diskGB: number };
export type ImageOpt = { id: string; name: string; family: string };
export type GamePlanRow = {
  id: string;
  gameFamily: string;
  name: string;
  ramMB: number;
  cpuCores: number;
  diskGB: number;
  slots: number | null;
  priceCents: number;
  termMonths: number;
  basePlanId: string;
  osTemplateId: string | null;
  featured: boolean;
  active: boolean;
  sortOrder: number;
};

const GAME_FAMILIES = ["minecraft", "valheim", "rust", "palworld", "cs2", "terraria"] as const;

/**
 * Create/edit form for a single GamePlan tier. Used both inline on each existing
 * tier (collapsed behind an "Edit" toggle) and as the bottom "new tier" card.
 */
export function GamePlanForm({
  plan,
  plans,
  images,
  defaultGame,
  onSaved,
}: {
  plan?: GamePlanRow;
  plans: PlanOpt[];
  images: ImageOpt[];
  defaultGame?: string;
  onSaved?: () => void;
}) {
  const [state, action, pending] = useActionState(adminSaveGamePlan, {} as { error?: string; ok?: boolean });
  const formRef = useRef<HTMLFormElement>(null);
  const [game, setGame] = useState(plan?.gameFamily ?? defaultGame ?? GAME_FAMILIES[0]);

  useEffect(() => {
    if (state?.ok) {
      if (!plan) formRef.current?.reset();
      onSaved?.();
    }
  }, [state, plan, onSaved]);

  const gameImages = images.filter((i) => i.family === game);

  return (
    <form ref={formRef} action={action} className="grid grid-cols-2 gap-3 sm:grid-cols-4">
      {plan && <input type="hidden" name="id" value={plan.id} />}
      {state?.error && (
        <div className="col-span-full rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
          {state.error}
        </div>
      )}
      {state?.ok && (
        <div className="col-span-full rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
          Saved.
        </div>
      )}

      <div>
        <label className="label">Game</label>
        <select className="input" name="gameFamily" value={game} onChange={(e) => setGame(e.target.value)}>
          {GAME_FAMILIES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>
      </div>
      <div className="col-span-2">
        <label className="label">Tier name</label>
        <input className="input" name="name" defaultValue={plan?.name} placeholder="Minecraft — 4 GB / 20 slots" required />
      </div>
      <div>
        <label className="label">Slots</label>
        <input className="input" name="slots" type="number" min={1} defaultValue={plan?.slots ?? ""} placeholder="20" />
      </div>

      <div>
        <label className="label">RAM (MB)</label>
        <input className="input" name="ramMB" type="number" min={256} defaultValue={plan?.ramMB ?? 4096} required />
      </div>
      <div>
        <label className="label">vCPU</label>
        <input className="input" name="cpuCores" type="number" min={1} defaultValue={plan?.cpuCores ?? 2} required />
      </div>
      <div>
        <label className="label">Disk (GB)</label>
        <input className="input" name="diskGB" type="number" min={1} defaultValue={plan?.diskGB ?? 30} required />
      </div>
      <div>
        <label className="label">Sort order</label>
        <input className="input" name="sortOrder" type="number" min={0} defaultValue={plan?.sortOrder ?? 0} />
      </div>

      <div>
        <label className="label">Price (cents)</label>
        <input className="input" name="priceCents" type="number" min={0} defaultValue={plan?.priceCents ?? 999} required />
      </div>
      <div>
        <label className="label">Term (months)</label>
        <input className="input" name="termMonths" type="number" min={1} max={36} defaultValue={plan?.termMonths ?? 1} required />
      </div>
      <div>
        <label className="label">Base VPS plan</label>
        <select className="input" name="basePlanId" defaultValue={plan?.basePlanId ?? ""} required>
          <option value="" disabled>
            Choose plan…
          </option>
          {plans.map((p) => (
            <option key={p.id} value={p.id}>
              {p.name} · {(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)}GB / {p.diskGB}GB
            </option>
          ))}
        </select>
        <p className="mt-1 text-[11px] text-slate-500">Sizes the provisioned VM</p>
      </div>
      <div>
        <label className="label">Game image</label>
        <select className="input" name="osTemplateId" defaultValue={plan?.osTemplateId ?? ""}>
          <option value="">Auto (any {game} image)</option>
          {gameImages.map((i) => (
            <option key={i.id} value={i.id}>
              {i.name}
            </option>
          ))}
        </select>
      </div>

      <div className="col-span-full flex flex-wrap items-center gap-4">
        <label className="flex items-center gap-2 text-sm">
          <input type="checkbox" name="active" defaultChecked={plan ? plan.active : true} /> Active
        </label>
        <label className="flex items-center gap-2 text-sm">
          <input type="checkbox" name="featured" defaultChecked={plan?.featured ?? false} /> Featured
        </label>
        <button className="btn-primary ml-auto" disabled={pending}>
          {pending ? "Saving…" : plan ? "Save changes" : "Create tier"}
        </button>
      </div>
    </form>
  );
}

/** Expand/collapse wrapper so each existing tier's edit form is tucked away. */
export function GamePlanEditor(props: {
  plan: GamePlanRow;
  plans: PlanOpt[];
  images: ImageOpt[];
}) {
  const [open, setOpen] = useState(false);
  return (
    <div>
      <button className="btn-secondary py-1 text-xs" onClick={() => setOpen((o) => !o)}>
        {open ? "Close" : "Edit"}
      </button>
      {open && (
        <div className="mt-3 border-t border-white/[0.06] pt-3">
          <GamePlanForm plan={props.plan} plans={props.plans} images={props.images} onSaved={() => setOpen(false)} />
        </div>
      )}
    </div>
  );
}

export function ToggleGamePlanButton({ id, active }: { id: string; active: boolean }) {
  const [pending, start] = useTransition();
  return (
    <button
      className={active ? "btn-secondary py-1 text-xs" : "btn-primary py-1 text-xs"}
      disabled={pending}
      onClick={() => start(() => adminToggleGamePlan(id))}
    >
      {active ? "Disable" : "Enable"}
    </button>
  );
}

export function DeleteGamePlanButton({ id, name }: { id: string; name: string }) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  return (
    <span className="inline-flex items-center gap-2">
      {error && <span className="text-xs text-red-400">{error}</span>}
      <button
        className="btn-danger py-1 text-xs"
        disabled={pending}
        onClick={() => {
          if (!confirm(`Delete tier "${name}"?`)) return;
          setError(null);
          start(async () => {
            const res = await adminDeleteGamePlan(id);
            if (res?.error) setError(res.error);
          });
        }}
      >
        Delete
      </button>
    </span>
  );
}

import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge, fmtMoney } from "@/components/ui/primitives";
import { GAME_FAMILIES } from "@/lib/games";
import {
  GamePlanForm,
  GamePlanEditor,
  ToggleGamePlanButton,
  DeleteGamePlanButton,
  type GamePlanRow,
  type PlanOpt,
  type ImageOpt,
} from "@/components/admin/GamePlanControls";

export const dynamic = "force-dynamic";

const GAME_LABEL: Record<string, string> = {
  minecraft: "Minecraft",
  valheim: "Valheim",
  rust: "Rust",
  palworld: "Palworld",
  cs2: "Counter-Strike 2",
  terraria: "Terraria",
};

function gb(mb: number) {
  return `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
}

export default async function AdminGamePlansPage() {
  await requireArea("billing");

  const [gamePlans, plans, images] = await Promise.all([
    db.gamePlan.findMany({
      include: { _count: { select: { servers: true } } },
      orderBy: [{ gameFamily: "asc" }, { sortOrder: "asc" }, { priceCents: "asc" }],
    }),
    db.plan.findMany({ orderBy: { sortOrder: "asc" } }),
    db.osTemplate.findMany({
      where: { family: { in: [...GAME_FAMILIES] }, category: "APPLICATION" },
      orderBy: { name: "asc" },
    }),
  ]);

  const planOpts: PlanOpt[] = plans.map((p) => ({ id: p.id, name: p.name, ramMB: p.ramMB, diskGB: p.diskGB }));
  const imageOpts: ImageOpt[] = images.map((i) => ({ id: i.id, name: i.name, family: i.family }));
  const rows: GamePlanRow[] = gamePlans.map((g) => ({
    id: g.id,
    gameFamily: g.gameFamily,
    name: g.name,
    ramMB: g.ramMB,
    cpuCores: g.cpuCores,
    diskGB: g.diskGB,
    slots: g.slots,
    priceCents: g.priceCents,
    termMonths: g.termMonths,
    basePlanId: g.basePlanId,
    osTemplateId: g.osTemplateId,
    featured: g.featured,
    active: g.active,
    sortOrder: g.sortOrder,
  }));

  const planName = new Map(plans.map((p) => [p.id, p.name]));
  const imageName = new Map(images.map((i) => [i.id, i.name]));
  const counts = new Map(gamePlans.map((g) => [g.id, g._count.servers]));

  // Group tiers by game, preserving GAME_FAMILIES order.
  const byGame = new Map<string, GamePlanRow[]>();
  for (const fam of GAME_FAMILIES) byGame.set(fam, []);
  for (const r of rows) {
    if (!byGame.has(r.gameFamily)) byGame.set(r.gameFamily, []);
    byGame.get(r.gameFamily)!.push(r);
  }

  return (
    <div>
      <PageHeader
        title="Game plans"
        sub="Per-game pricing tiers. Each tier provisions a VM sized by its base VPS plan, running the game image."
      >
        <Badge tone="brand">{rows.length} tiers</Badge>
      </PageHeader>

      {plans.length === 0 && (
        <div className="mb-6 rounded-2xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
          No VPS plans exist yet — create Plans first, since each tier needs a base plan for sizing.
        </div>
      )}

      <div className="space-y-8">
        {[...byGame.entries()].map(([fam, tiers]) => (
          <section key={fam}>
            <h2 className="mb-3 flex items-center gap-2 text-lg font-semibold">
              {GAME_LABEL[fam] ?? fam}
              <span className="text-sm font-normal text-slate-500">
                {tiers.length} tier{tiers.length === 1 ? "" : "s"}
              </span>
            </h2>
            <div className="space-y-3">
              {tiers.length === 0 && (
                <p className="text-sm text-slate-500">No tiers yet — add one below.</p>
              )}
              {tiers.map((t) => (
                <div key={t.id} className="card">
                  <div className="flex flex-wrap items-center justify-between gap-3">
                    <div className="min-w-0">
                      <div className="flex flex-wrap items-center gap-2">
                        <span className="font-semibold text-white">{t.name}</span>
                        {t.featured && <Badge tone="brand">Featured</Badge>}
                        <Badge tone={t.active ? "success" : "muted"}>{t.active ? "Active" : "Disabled"}</Badge>
                      </div>
                      <p className="mt-1 text-sm text-slate-400">
                        {gb(t.ramMB)} RAM · {t.cpuCores} vCPU · {t.diskGB} GB disk
                        {t.slots != null && ` · ${t.slots} slots`} ·{" "}
                        <span className="text-white">{fmtMoney(t.priceCents)}</span>
                        {t.termMonths > 1 ? ` / ${t.termMonths} mo` : " / mo"}
                      </p>
                      <p className="mt-0.5 text-xs text-slate-500">
                        Base plan: {planName.get(t.basePlanId) ?? "—"} · Image:{" "}
                        {t.osTemplateId ? imageName.get(t.osTemplateId) ?? "—" : "auto"} ·{" "}
                        {counts.get(t.id) ?? 0} server(s)
                      </p>
                    </div>
                    <div className="flex flex-wrap items-center gap-2">
                      <ToggleGamePlanButton id={t.id} active={t.active} />
                      <DeleteGamePlanButton id={t.id} name={t.name} />
                    </div>
                  </div>
                  <div className="mt-3">
                    <GamePlanEditor plan={t} plans={planOpts} images={imageOpts} />
                  </div>
                </div>
              ))}

              <div className="card border-dashed">
                <p className="mb-3 text-sm text-slate-400">Add a {GAME_LABEL[fam] ?? fam} tier</p>
                <GamePlanForm plans={planOpts} images={imageOpts} defaultGame={fam} />
              </div>
            </div>
          </section>
        ))}
      </div>
    </div>
  );
}

