"use client";

import { useMemo, useState, useTransition } from "react";
import { orderGameServer } from "@/lib/actions-gameplans";

export type Tier = {
  id: string;
  gameFamily: string;
  name: string;
  ramMB: number;
  cpuCores: number;
  diskGB: number;
  slots: number | null;
  priceCents: number;
  termMonths: number;
  featured: boolean;
};
export type GameMeta = { family: string; name: string; glyph: string };

const money = (c: number) => `$${(c / 100).toFixed(2)}`;
const gb = (mb: number) => `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;

/**
 * Customer game-server deploy: pick a game, pick a tier, deploy. Charges the
 * tier's price from the wallet via orderGameServer (which redirects to the new
 * server on success).
 */
export function GameDeploy({
  games,
  tiers,
  balanceCents,
}: {
  games: GameMeta[];
  tiers: Tier[];
  balanceCents: number;
}) {
  const firstGame = games[0]?.family ?? "";
  const [game, setGame] = useState(firstGame);
  const [selected, setSelected] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const gameTiers = useMemo(
    () => tiers.filter((t) => t.gameFamily === game).sort((a, b) => a.priceCents - b.priceCents),
    [tiers, game],
  );

  const chosen = gameTiers.find((t) => t.id === selected) ?? null;
  const insufficient = chosen ? balanceCents < chosen.priceCents : false;

  function deploy() {
    if (!chosen) return;
    setError(null);
    start(async () => {
      const res = await orderGameServer(chosen.id);
      // On success orderGameServer redirects; only errors return here.
      if (res?.error) setError(res.error);
    });
  }

  return (
    <div className="space-y-6">
      {/* Step 1 — game */}
      <div>
        <p className="label mb-2">1 · Choose a game</p>
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-6">
          {games.map((g) => {
            const active = g.family === game;
            const count = tiers.filter((t) => t.gameFamily === g.family).length;
            return (
              <button
                key={g.family}
                onClick={() => {
                  setGame(g.family);
                  setSelected(null);
                  setError(null);
                }}
                className={`card card-hover flex flex-col items-center gap-1.5 py-4 text-center transition ${
                  active ? "border-brand-400 ring-1 ring-brand-400/40" : ""
                }`}
              >
                <span className="text-2xl">{g.glyph}</span>
                <span className="text-sm font-medium text-white">{g.name}</span>
                <span className="text-[11px] text-slate-500">
                  {count} tier{count === 1 ? "" : "s"}
                </span>
              </button>
            );
          })}
        </div>
      </div>

      {/* Step 2 — tier */}
      <div>
        <p className="label mb-2">2 · Choose a plan</p>
        {gameTiers.length === 0 ? (
          <p className="text-sm text-slate-500">No plans are available for this game yet. Check back soon.</p>
        ) : (
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
            {gameTiers.map((t) => {
              const active = t.id === selected;
              return (
                <button
                  key={t.id}
                  onClick={() => {
                    setSelected(t.id);
                    setError(null);
                  }}
                  className={`card card-hover text-left transition ${
                    active ? "border-brand-400 ring-1 ring-brand-400/40" : ""
                  }`}
                >
                  <div className="flex items-center justify-between gap-2">
                    <span className="font-semibold text-white">{t.name}</span>
                    {t.featured && (
                      <span className="rounded-full border border-brand-500/40 bg-brand-500/10 px-2 py-0.5 text-[11px] text-brand-300">
                        Popular
                      </span>
                    )}
                  </div>
                  <p className="mt-2 text-2xl font-bold tracking-tight text-white">
                    {money(t.priceCents)}
                    <span className="text-sm font-normal text-slate-400">
                      {t.termMonths > 1 ? ` / ${t.termMonths} mo` : " / mo"}
                    </span>
                  </p>
                  <ul className="mt-3 space-y-1 text-sm text-slate-400">
                    <li>{gb(t.ramMB)} RAM · {t.cpuCores} vCPU</li>
                    <li>{t.diskGB} GB NVMe disk</li>
                    {t.slots != null && <li>Up to {t.slots} player slots</li>}
                  </ul>
                </button>
              );
            })}
          </div>
        )}
      </div>

      {/* Step 3 — deploy */}
      {chosen && (
        <div className="card flex flex-wrap items-center justify-between gap-4">
          <div>
            <p className="text-sm text-slate-400">
              Deploying <span className="font-medium text-white">{chosen.name}</span>. You&apos;ll be charged{" "}
              <span className="font-medium text-white">{money(chosen.priceCents)}</span> from your wallet
              (balance {money(balanceCents)}).
            </p>
            {error && <p className="mt-1 text-sm text-red-400">{error}</p>}
            {insufficient && !error && (
              <p className="mt-1 text-sm text-amber-400">Insufficient balance — top up your wallet first.</p>
            )}
          </div>
          <button className="btn-primary" disabled={pending || insufficient} onClick={deploy}>
            {pending ? "Deploying…" : "Deploy server"}
          </button>
        </div>
      )}
    </div>
  );
}

